//! Deterministic randomized differential testing: the engine must agree with
//! the independently-implemented naive oracle on many randomly generated
//! shapes, densities and duplicate multiplicities. A hand-seeded LCG makes
//! every run reproducible; nothing here is generated by the engine itself.

mod support;

use leapfrog_triejoin::lftj::JoinEngine;
use leapfrog_triejoin::naive::{multisets_equal, NaiveOracle};
use leapfrog_triejoin::plan::{NullPolicy, Plan};
use support::{int_relation, Lcg};

fn trial_two_tables(seed: u64, a_dom: u64, b_dom: u64, c_dom: u64, density_pct: u64, dup_max: u64) {
    let mut rng = Lcg::new(seed);
    let mut r_rows: Vec<Vec<i64>> = Vec::new();
    let mut s_rows: Vec<Vec<i64>> = Vec::new();

    for a in 0..a_dom {
        for b in 0..b_dom {
            if rng.below(100) < density_pct {
                let copies = 1 + rng.below(dup_max);
                for _ in 0..copies {
                    r_rows.push(vec![a as i64, b as i64]);
                }
            }
        }
    }
    for b in 0..b_dom {
        for c in 0..c_dom {
            if rng.below(100) < density_pct {
                let copies = 1 + rng.below(dup_max);
                for _ in 0..copies {
                    s_rows.push(vec![b as i64, c as i64]);
                }
            }
        }
    }

    // Every trial must stay inside the validated envelope and share 'b'.
    let r = int_relation("R", &["a", "b"], r_rows);
    let s = int_relation("S", &["b", "c"], s_rows);
    let plan = match Plan::natural_join(vec![r, s], NullPolicy::SqlMatchNever, 6) {
        Ok(p) => p,
        // An empty relation is a valid input that yields an empty answer.
        Err(_) => return,
    };

    let engine = JoinEngine::build(plan.clone()).run(None, None, None);
    let oracle = NaiveOracle::new(&plan).enumerate();

    assert_eq!(
        engine.stats.emitted_rows, oracle.stats.emitted_rows,
        "seed {seed}: row counts differ"
    );
    assert!(
        multisets_equal(&engine.rows, &oracle.rows),
        "seed {seed}: result multisets differ"
    );
    assert_eq!(engine.stats.intermediate_tuples_materialized, 0);
}

#[test]
fn many_random_two_table_joins_match_the_oracle() {
    let mut seed = 0x1234_5678_u64;
    for trial in 0..60 {
        seed ^= seed << 13;
        seed ^= seed >> 7;
        seed ^= seed << 17;
        let a_dom = 1 + seed % 6;
        let b_dom = 1 + (seed >> 8) % 6;
        let c_dom = 1 + (seed >> 16) % 6;
        let density = 10 + (seed >> 24) % 80;
        let dup_max = 1 + (seed >> 32) % 3;
        trial_two_tables(seed ^ trial, a_dom, b_dom, c_dom, density, dup_max);
    }
}

#[test]
fn random_triangle_shapes_match_the_oracle() {
    let mut seed = 0xabcdef01_u64;
    for _ in 0..30 {
        seed ^= seed.wrapping_mul(0x9e37_79b9_7f4a_7c15);
        let n = 2 + seed % 7;

        // Randomly oriented edge sets used consistently across all three
        // relations of the triangle (valid triangles only need consistent
        // membership, orientation is irrelevant for multiset membership).
        let mut rng = Lcg::new(seed);
        let mut edges: Vec<Vec<i64>> = Vec::new();
        for i in 0..n as i64 {
            for j in (i + 1)..n as i64 {
                if rng.below(100) < 60 {
                    let copies = 1 + rng.below(2);
                    for _ in 0..copies {
                        edges.push(vec![i, j]);
                    }
                }
            }
        }

        let r = int_relation("R", &["a", "b"], edges.clone());
        let s = int_relation("S", &["b", "c"], edges.clone());
        let t = int_relation("T", &["a", "c"], edges);
        if let Ok(plan) = Plan::natural_join(vec![r, s, t], NullPolicy::Reject, 6) {
            let engine = JoinEngine::build(plan.clone()).run(None, None, None);
            let oracle = NaiveOracle::new(&plan).enumerate();
            assert_eq!(engine.stats.emitted_rows, oracle.stats.emitted_rows);
            assert!(multisets_equal(&engine.rows, &oracle.rows));
            assert_eq!(engine.stats.intermediate_tuples_materialized, 0);
        }
    }
}

#[test]
fn empty_relations_yield_empty_results_without_incident() {
    let r = int_relation("R", &["a", "b"], vec![]);
    let s = int_relation("S", &["b", "c"], vec![vec![1, 2]]);
    let plan = Plan::natural_join(vec![r, s], NullPolicy::Reject, 6).unwrap();
    let engine = JoinEngine::build(plan.clone()).run(None, None, None);
    let oracle = NaiveOracle::new(&plan).enumerate();
    assert_eq!(engine.stats.emitted_rows, 0);
    assert_eq!(oracle.stats.emitted_rows, 0);
}
